                    </div></div><!-- Escenario C: Llegó dañado --><form method="POST" class="border-2 border-amber-200 bg-amber-50 rounded-xl p-4 hover:shadow-md transition cursor-pointer"><?= emxCsrfCampo() ?><div class="flex items-start gap-3"><input type="radio" name="accion_confirmacion" value="confirmar_danado" id="esc_c" class="mt-1 w-4 h-4 text-amber-600"><label for="esc_c" class="flex-1 cursor-pointer"><span class="font-bold text-amber-800 block">Llegó, pero está dañado o incompleto</span><span class="text-xs text-amber-700">Se abrirá un caso de devolución. Admin autoriza retorno, inspección y luego habilita reembolso o cambio.</span></label></div></form></div><div class="bg-slate-50 p-4 flex justify-end gap-3 border-t"><button onclick="cerrarModalConfirmacion()" class="px-4 py-2 text-slate-600 font-medium hover:bg-slate-200 rounded-lg transition">Cancelar</button><button onclick="enviarConfirmacion()" class="px-6 py-2 bg-blue-600 text-white font-bold rounded-lg hover:bg-blue-700 transition shadow-lg">Enviar Confirmación
                </button></div></div></div><?php if (is_file(EMX_VIEWS_PATH . '/components/footer.php')) include EMX_VIEWS_PATH . '/components/footer.php'; ?><script>function abrirModalConfirmacion() {
            document.getElementById('modalConfirmacion').classList.remove('hidden');
            document.body.style.overflow = 'hidden';
        }

        function cerrarModalConfirmacion() {
            document.getElementById('modalConfirmacion').classList.add('hidden');
            document.body.style.overflow = '';
        }

        function enviarConfirmacion() {
            const accion = document.querySelector('input[name="accion_confirmacion"]:checked');
            if (!accion) {
                emxAlert('Por favor selecciona una opción.');
                return;
            }
            
            emxConfirm('¿Estás seguro de enviar esta confirmación?', function () {
                // Crear form dinámico
                const form = document.createElement('form');
                form.method = 'POST';
                form.action = '';

                const inputCsrf = document.createElement('input');
                inputCsrf.type = 'hidden';
                inputCsrf.name = 'csrf_token';
                inputCsrf.value = <?= json_encode(emxCsrfToken()) ?>;
                form.appendChild(inputCsrf);
                
                const inputAccion = document.createElement('input');
                inputAccion.type = 'hidden';
                inputAccion.name = 'accion_tracking';
                inputAccion.value = accion.value;
                form.appendChild(inputAccion);
                
                document.body.appendChild(form);
                form.submit();
            });
        }

        document.getElementById('modalConfirmacion').addEventListener('click', function(e) {
            if (e.target === this) cerrarModalConfirmacion();
        });
    </script><script src="assets/emx_modales.js"></script></body></html>